using namespace wpp;using Clock=std::chrono::steady_clock;using Time=Clock::time_point;
struct Timeout:std::runtime_error{Timeout():runtime_error("absolute deadline expired") {}};
static uint64_t ns(Time a,Time b){return uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(b-a).count());}
static void check_time(Time end){if(Clock::now()>=end)throw Timeout();}
struct FD {int fd=-1;explicit FD(int f=-1):fd(f){}~FD(){if(fd>=0)close(fd);}FD(const FD&)=delete;FD&operator=(const FD&)=delete;FD(FD&&o)noexcept:fd(o.fd){o.fd=-1;}FD&operator=(FD&&o)noexcept{if(this!=&o){if(fd>=0)close(fd);fd=o.fd;o.fd=-1;}return *this;}};
static void nonblock(int f){int flags=fcntl(f,F_GETFL);need(flags>=0&&fcntl(f,F_SETFL,flags|O_NONBLOCK)==0,"nonblocking socket");}
static void wait_fd(int f,short events,Time end){for(;;){check_time(end);auto remain=std::chrono::duration_cast<std::chrono::milliseconds>(end-Clock::now()).count();pollfd p{f,events,0};int r=poll(&p,1,int(std::max<int64_t>(1,std::min<int64_t>(5,remain))));if(r<0&&errno==EINTR)continue;need(r>=0,"poll failure");if(r>0){need(!(p.revents&(POLLERR|POLLNVAL)),"socket poll error");if(p.revents&(events|POLLHUP))return;}}}
static sockaddr_in address(const std::string&s,uint16_t port){sockaddr_in a{};a.sin_family=AF_INET;a.sin_port=htons(port);need(inet_pton(AF_INET,s.c_str(),&a.sin_addr)==1,"IPv4 address");uint32_t ip=ntohl(a.sin_addr.s_addr);need(ip!=0&&ip!=0xffffffffu&&(ip>>28)<0xe,"explicit unicast IPv4 required");return a;}
static FD socket_bound(bool tcp,const sockaddr_in&a){FD s(socket(AF_INET,(tcp?SOCK_STREAM:SOCK_DGRAM)|SOCK_CLOEXEC,0));need(s.fd>=0,"socket creation");nonblock(s.fd);need(bind(s.fd,reinterpret_cast<const sockaddr*>(&a),sizeof(a))==0,"bind explicit local address");if(tcp){int yes=1;need(setsockopt(s.fd,IPPROTO_TCP,TCP_NODELAY,&yes,sizeof(yes))==0,"TCP_NODELAY");}return s;}
static void connect_to(int f,const sockaddr_in&a,Time end){int r=connect(f,reinterpret_cast<const sockaddr*>(&a),sizeof(a));if(r<0){need(errno==EINPROGRESS,"connect failed");wait_fd(f,POLLOUT,end);int e=0;socklen_t n=sizeof(e);need(getsockopt(f,SOL_SOCKET,SO_ERROR,&e,&n)==0&&e==0,"connection failed");}}
static void stream_write(int f,View b,Time end,uint64_t&bytes){size_t at=0;while(at<b.size()){check_time(end);ssize_t n=send(f,b.data()+at,b.size()-at,MSG_DONTWAIT|MSG_NOSIGNAL);if(n<0){if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){wait_fd(f,POLLOUT,end);continue;}throw std::runtime_error("TCP send");}need(n>0,"TCP closed during send");at+=size_t(n);bytes+=size_t(n);}}
static void stream_read(int f,std::span<uint8_t>b,Time end,uint64_t&bytes,Time*first){size_t at=0;while(at<b.size()){check_time(end);ssize_t n=recv(f,b.data()+at,b.size()-at,MSG_DONTWAIT);if(n<0){if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){wait_fd(f,POLLIN,end);continue;}throw std::runtime_error("TCP receive");}need(n>0,"TCP closed during receive");if(first&&*first==Time{}){*first=Clock::now();end=std::min(end,*first+std::chrono::milliseconds(100));}at+=size_t(n);bytes+=size_t(n);}}
static void send_record(int f,bool tcp,View b,Time end,uint64_t&bytes,const sockaddr_in*peer=nullptr){if(tcp){Bytes framed(b.size()+2);put(framed,0,b.size(),2);std::copy(b.begin(),b.end(),framed.begin()+2);stream_write(f,framed,end,bytes);return;}for(;;){check_time(end);ssize_t n=peer?sendto(f,b.data(),b.size(),MSG_DONTWAIT|MSG_NOSIGNAL,reinterpret_cast<const sockaddr*>(peer),sizeof(*peer)):send(f,b.data(),b.size(),MSG_DONTWAIT|MSG_NOSIGNAL);if(n<0){if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){wait_fd(f,POLLOUT,end);continue;}throw std::runtime_error("UDP send");}need(size_t(n)==b.size(),"short UDP send");bytes+=size_t(n);return;}}
struct Received {Bytes bytes;sockaddr_in peer{};Time first;};
static Received receive_record(int f,bool tcp,Time end,uint64_t&bytes){Received r; r.first=Time{};if(tcp){Bytes size(2);stream_read(f,size,end,bytes,&r.first);auto n=get(size,0,2);need(n>=header&&n<=max_record,"TCP record length");r.bytes.resize(n);end=std::min(end,r.first+std::chrono::milliseconds(100));stream_read(f,r.bytes,end,bytes,nullptr);return r;}r.bytes.resize(max_record);for(;;){check_time(end);socklen_t len=sizeof(r.peer);ssize_t n=recvfrom(f,r.bytes.data(),r.bytes.size(),MSG_DONTWAIT|MSG_TRUNC,reinterpret_cast<sockaddr*>(&r.peer),&len);if(n<0){if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK){wait_fd(f,POLLIN,end);continue;}throw std::runtime_error("UDP receive");}r.first=Clock::now();need(len==sizeof(r.peer)&&r.peer.sin_family==AF_INET&&n>0&&size_t(n)<=max_record,"UDP truncated/address record");bytes+=size_t(n);r.bytes.resize(size_t(n));return r;}}
struct Row {uint32_t frame=0;bool complete=false;uint64_t rtt_ns=0,assembly_ns=0,start_offset_ns=0,complete_offset_ns=0;bool has_start=false;unsigned unique=0,duplicates=0;uint64_t left_hash=0,right_hash=0;};
struct Report {std::vector<Row>rows;uint64_t sent_bytes=0,received_bytes=0,rejected=0,stale=0,sent_records=0;bool aborted=false;};
static void row_hash(Row&r,const Assembly&a){size_t half=a.received.size()/2;r.left_hash=hash(View(a.received).first(half));r.right_hash=hash(View(a.received).subspan(half));}
static Report sender(const Config&c,bool tcp,int f,Time global){Report result;Time origin=Clock::now(),next=origin;for(uint32_t frame=1;frame<=c.frames;++frame){std::this_thread::sleep_until(next);check_time(global);auto source=pair(c,frame);std::vector<Bytes>records;for(unsigned i=0;i<count(c);++i)records.push_back(data(c,frame,i,source));Time start=Clock::now(),end=std::min(global,start+std::chrono::milliseconds(100));next=start+std::chrono::nanoseconds(1000000000/c.hz);Row row;row.frame=frame;row.has_start=true;row.start_offset_ns=ns(origin,start);
 try{for(auto&b:records){send_record(f,tcp,b,end,result.sent_bytes);++result.sent_records;}for(;;){auto incoming=receive_record(f,tcp,end,result.received_bytes);try{auto r=parse(c,incoming.bytes);if(r.frame!=frame){++result.stale;continue;}row.assembly_ns=check_ack(c,r,frame);row.rtt_ns=ns(start,Clock::now());row.complete_offset_ns=row.start_offset_ns+row.rtt_ns;need(row.rtt_ns<=100000000,"sender ACK deadline");row.complete=true;row.unique=count(c);break;}catch(const std::runtime_error&){if(tcp)throw;if(++result.rejected>1024)throw std::runtime_error("rejection bound");}}}
 catch(const Timeout&){if(tcp)result.aborted=true;}result.rows.push_back(row);if(result.aborted)break;}return result;}
static Report receiver(const Config&c,bool tcp,int f,const sockaddr_in&expected,Time global){Report result;Time origin=Clock::now();std::optional<Received>pending;uint16_t locked_port=0;for(uint32_t frame=1;frame<=c.frames;++frame){if(Clock::now()>=global){result.aborted=true;break;}Assembly assembly(c,frame);Row row;row.frame=frame;Time first{};Time end=std::min(global,Clock::now()+std::chrono::milliseconds(frame==1?5000:500));
 try{for(;;){Received incoming;if(pending){incoming=std::move(*pending);pending.reset();}else incoming=receive_record(f,tcp,end,result.received_bytes);
 if(!tcp&&(incoming.peer.sin_addr.s_addr!=expected.sin_addr.s_addr||(locked_port&&incoming.peer.sin_port!=locked_port))){if(++result.rejected>1024)throw std::runtime_error("peer rejection bound");continue;}
 std::optional<Record> rec;try{rec=parse(c,incoming.bytes);need(rec->kind==1,"receiver expected DATA");}catch(const std::runtime_error&){if(tcp)throw;if(++result.rejected>1024)throw std::runtime_error("rejection bound");continue;}
 if(!tcp&&!locked_port)locked_port=incoming.peer.sin_port;
 if(rec->frame<frame){++result.stale;continue;}if(rec->frame>frame){pending=std::move(incoming);break;}
 if(first==Time{}){first=incoming.first;row.has_start=true;row.start_offset_ns=ns(origin,first);end=std::min(global,first+std::chrono::milliseconds(100));}check_time(end);
 try{row.complete=assembly.accept(*rec);}catch(const std::runtime_error&){if(tcp)throw;if(++result.rejected>1024)throw std::runtime_error("rejection bound");continue;}
 if(row.complete){Time completed=Clock::now();row.assembly_ns=ns(first,completed);row.complete_offset_ns=ns(origin,completed);check_time(end);row_hash(row,assembly);auto response=ack(c,frame,row.assembly_ns);send_record(f,tcp,response,end,result.sent_bytes,tcp?nullptr:&incoming.peer);++result.sent_records;break;}}
 }catch(const Timeout&){row.complete=false;if(tcp)result.aborted=true;}row.unique=assembly.unique;row.duplicates=assembly.duplicates;result.rows.push_back(row);if(result.aborted)break;}return result;}
static unsigned number(const char*s){std::string t(s);need(!t.empty()&&std::all_of(t.begin(),t.end(),[](char c){return c>='0'&&c<='9';}),"numeric argument");auto x=std::stoull(t);need(x<=UINT32_MAX,"number bound");return unsigned(x);}
static std::string token_text(const Config&c){static constexpr char hex[]="0123456789abcdef";std::string s;for(auto b:c.token){s+=hex[b>>4];s+=hex[b&15];}return s;}
static void print(const Config&c,const Report&r,bool send,bool tcp,const std::string&local,const std::string&peer,unsigned port,int recvbuf,int sendbuf){unsigned complete=0;for(auto&row:r.rows)complete+=row.complete;std::cout<<"{\"schema\":1,\"role\":\""<<(send?"sender":"receiver")<<"\",\"transport\":\""<<(tcp?"tcp":"udp")<<"\",\"scope\":\"explicit-peer synthetic complete-stereo bytes; no codec/OpenXR; no one-way cross-clock latency\",\"local_ipv4\":\""<<local<<"\",\"peer_ipv4\":\""<<peer<<"\",\"port\":"<<port<<",\"run_token\":\""<<token_text(c)<<"\",\"planned_pairs\":"<<c.frames<<",\"pair_bytes\":"<<c.pair_bytes<<",\"planned_source_pair_bytes\":"<<uint64_t(c.frames)*c.pair_bytes<<",\"hz\":"<<c.hz<<",\"data_records_per_pair\":"<<count(c)<<",\"max_record_bytes\":1200,\"pair_deadline_ms\":100,\"complete_pairs\":"<<complete<<",\"processed_pairs\":"<<r.rows.size()<<",\"incomplete_processed_pairs\":"<<r.rows.size()-complete<<",\"unprocessed_pairs\":"<<c.frames-r.rows.size()<<",\"aborted\":"<<(r.aborted?"true":"false")<<",\"application_bytes_sent\":"<<r.sent_bytes<<",\"application_bytes_received\":"<<r.received_bytes<<",\"records_sent\":"<<r.sent_records<<",\"counted_ipv4_udp_bytes_sent\":";if(tcp)std::cout<<"null";else std::cout<<r.sent_bytes+28*r.sent_records;
 std::cout<<",\"physical_wire_bytes_measured\":false,\"rejected_records\":"<<r.rejected<<",\"stale_records\":"<<r.stale<<",\"socket_receive_buffer\":"<<recvbuf<<",\"socket_send_buffer\":"<<sendbuf<<",\"tcp_nodelay\":"<<(tcp?"true":"false")<<",\"rows\":[";unsigned n=0;for(auto&row:r.rows){std::cout<<(n++?",":"")<<"{\"frame\":"<<row.frame<<",\"complete\":"<<(row.complete?"true":"false")<<",\"unique_records\":"<<row.unique<<",\"duplicates\":"<<row.duplicates<<",\"local_start_offset_ns\":";if(row.has_start)std::cout<<row.start_offset_ns;else std::cout<<"null";std::cout<<",\"local_complete_offset_ns\":";if(row.complete)std::cout<<row.complete_offset_ns;else std::cout<<"null";std::cout<<",\"sender_rtt_ns\":";if(send&&row.complete)std::cout<<row.rtt_ns;else std::cout<<"null";std::cout<<",\"receiver_assembly_ns\":";if(row.complete)std::cout<<row.assembly_ns;else std::cout<<"null";std::cout<<",\"left_fnv64\":";if(!send&&row.complete)std::cout<<'"'<<std::hex<<row.left_hash<<std::dec<<'"';else std::cout<<"null";std::cout<<",\"right_fnv64\":";if(!send&&row.complete)std::cout<<'"'<<std::hex<<row.right_hash<<std::dec<<'"';else std::cout<<"null";std::cout<<'}';}std::cout<<"]}\n";}
int main(int argc,char**argv){try{need(argc==10,"usage: probe send|receive tcp|udp LOCAL_IP PEER_IP PORT TOKEN32HEX FRAMES PAIR_BYTES HZ");bool sending=std::string(argv[1])=="send",tcp=std::string(argv[2])=="tcp";need(sending||std::string(argv[1])=="receive","role");need(tcp||std::string(argv[2])=="udp","transport");unsigned port=number(argv[5]);need(port>=49152&&port<=65535,"dedicated high port required");Config c{token(argv[6]),number(argv[7]),number(argv[8]),number(argv[9])};validate(c);auto local=address(argv[3],sending?0:uint16_t(port)),peer=address(argv[4],uint16_t(port));Time global=Clock::now()+std::chrono::seconds(30);FD socket=socket_bound(tcp,local);
 if(sending)connect_to(socket.fd,peer,std::min(global,Clock::now()+std::chrono::seconds(5)));
 else if(tcp){need(listen(socket.fd,1)==0,"TCP listen");Time end=std::min(global,Clock::now()+std::chrono::seconds(5));for(;;){wait_fd(socket.fd,POLLIN,end);sockaddr_in actual{};socklen_t len=sizeof(actual);FD accepted(accept4(socket.fd,reinterpret_cast<sockaddr*>(&actual),&len,SOCK_CLOEXEC|SOCK_NONBLOCK));if(accepted.fd<0&&(errno==EINTR||errno==EAGAIN||errno==EWOULDBLOCK))continue;need(accepted.fd>=0&&len==sizeof(actual)&&actual.sin_addr.s_addr==peer.sin_addr.s_addr,"TCP peer");int yes=1;need(setsockopt(accepted.fd,IPPROTO_TCP,TCP_NODELAY,&yes,sizeof(yes))==0,"accepted TCP_NODELAY");socket=std::move(accepted);break;}}
 int rb=0,sb=0;socklen_t len=sizeof(rb);need(getsockopt(socket.fd,SOL_SOCKET,SO_RCVBUF,&rb,&len)==0,"receive buffer query");len=sizeof(sb);need(getsockopt(socket.fd,SOL_SOCKET,SO_SNDBUF,&sb,&len)==0,"send buffer query");auto result=sending?sender(c,tcp,socket.fd,global):receiver(c,tcp,socket.fd,peer,global);print(c,result,sending,tcp,argv[3],argv[4],port,rb,sb);return result.aborted?2:0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
